def transform(grid):
    h,w=len(grid),len(grid[0])
    sep=None
    for c in range(1,w-1):
        col=[grid[r][c] for r in range(h)]
        if len(set(col))==1:
            others=set(grid[r][cc] for r in range(h) for cc in range(w) if cc!=c)
            if col[0] not in others:
                sep=c; break
    left_w=sep; right_w=w-sep-1; n=min(left_w,right_w)
    out=[]
    for r in range(h):
        left=grid[r][:sep][-n:]; right=grid[r][sep+1:][:n]
        out.append([2 if left[c]!=right[c] else 3 for c in range(n)])
    return out
